function validate([n, lamps, queries]) {
  if (!Number.isInteger(n) || n < 1 || n > 1e9) return 'n is between 1 and 10^9.';
  if (lamps.length > 20000 || queries.length > 20000) return 'lamps and queries have at most 20000 entries each.';
  for (const cell of [...lamps, ...queries]) {
    if (!Array.isArray(cell) || cell.length !== 2) return 'Each lamp and query is a [row, col] pair.';
    if (cell.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Rows and columns are between 0 and n - 1.';
  }
  return null;
}

