function gridIllumination(n, lamps, queries) {
  const rows = new Map();
  const cols = new Map();
  const diagonals = new Map();
  const antiDiagonals = new Map();
  const lampsOn = new Set();
  const add = (map, key, delta) => map.set(key, (map.get(key) ?? 0) + delta);
  const change = (row, col, delta) => {
    add(rows, row, delta);
    add(cols, col, delta);
    add(diagonals, row - col, delta);
    add(antiDiagonals, row + col, delta);
  };

  for (const [row, col] of lamps) {
    const key = `${row},${col}`;
    if (lampsOn.has(key)) continue;
    lampsOn.add(key);
    change(row, col, 1);
  }

  const answer = [];
  for (const [row, col] of queries) {
    const lit = rows.get(row) > 0 || cols.get(col) > 0 || diagonals.get(row - col) > 0 || antiDiagonals.get(row + col) > 0;
    answer.push(lit ? 1 : 0);
    for (let r = row - 1; r <= row + 1; r++) {
      for (let c = col - 1; c <= col + 1; c++) {
        if (lampsOn.delete(`${r},${c}`)) {
          change(r, c, -1);
        }
      }
    }
  }
  return answer;
}

