function gridIllumination(n, lamps, queries) {
  let on = [];
  for (const [r, c] of lamps) if (!on.some(([a, b]) => a === r && b === c)) on.push([r, c]);
  const result = [];
  for (const [qr, qc] of queries) {
    const shines = on.some(([r, c]) => r === qr || c === qc || r - c === qr - qc || r + c === qr + qc);
    result.push(shines ? 1 : 0);
    on = on.filter(([r, c]) => Math.abs(r - qr) > 1 || Math.abs(c - qc) > 1);
  }
  return result;
}

