function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 6);
    const cell = () => [int(0, n - 1), int(0, n - 1)];
    return [n, Array.from({ length: int(0, 8) }, cell), Array.from({ length: int(0, 8) }, cell)];
  }
  // Large grids keep lamps and queries inside a window so that they interact.
  const n = rand() < 0.5 ? int(100, 300) : 1000000000;
  const span = Math.min(n, int(40, 100));
  const baseRow = int(0, n - span);
  const baseCol = int(0, n - span);
  const cell = () => [baseRow + int(0, span - 1), baseCol + int(0, span - 1)];
  return [n, Array.from({ length: 2000 }, cell), Array.from({ length: 2000 }, cell)];
}
